  ui_story_30960401_95_dialog_content = "Sim, vou perguntar como ele morreu.",
  ui_story_30960401_96_dialog_content = "Ah, entendi...",
  ui_story_30960401_97_dialog_content = "Há doze anos. Não, foi há dez anos? Digamos há onze anos, que é a média.",
  ui_story_30960401_98_dialog_content = "Meu avô, <color=#FFB400>Amos</color>, morreu em Lumópolis.",
