  ui_story_30960401_113_dialog_content = "Preciso me encontrar com ela e perguntar o que aconteceu naquela época. Preciso saber o que houve com meu avô, Amos.",
  ui_story_30960401_114_dialog_content = "E quero saber... quem ela é de verdade.",
  ui_story_30960401_115_dialog_content = "Bom, até onde eu sei, o passado da Gabriela não é tão complicado... Mas eu não sei a história toda.",
