  ui_story_30960401_130_dialog_content = "Ou talvez... sob a sua supervisão, PlayerName?",
  ui_story_30960401_131_dialog_content = "Você tem muitos fardos para carregar, PlayerName... E um longo caminho.",
  ui_story_30960401_133_dialog_content = "Acabou tudo...",
  ui_story_30960401_134_dialog_content = "Por causa de... Demolição incontrolada e \"machucados sem intenção\".",
