  ui_story_30960401_154_dialog_content = "Amos... Esse era o nome do avô da Sariel.",
  ui_story_30960401_155_dialog_content = "É difícil imaginar a Gabriela envolvida em um mistério tão sinistro...",
  ui_story_30960401_156_dialog_content = "...",
  ui_story_30960401_157_dialog_content = "O que será que aconteceu há dez anos...",
  ui_story_30960601_1_dialog_content = "Com certeza o tempo está bom hoje...",
  ui_story_30960601_2_dialog_content = "<color=#e8d9bb>Estalo!</color>",
  ui_story_30960601_3_dialog_content = "De onde veio esse pedaço de papel?! Foi direto para o meu rosto...",
  ui_story_30960601_4_dialog_content = "Hum? Tem algo escrito nele...",
  ui_story_30960601_5_dialog_content = "\"Você deseja se tornar uma pessoa melhor? Você deseja ser bem sucedido?\"",
  ui_story_30960601_6_dialog_content = "\"Então venha até a Rising Star Agency e inscreva-se hoje!\"",
  ui_story_30960601_7_dialog_content = "\"Com todos os tipos de aulas e estilos de ensino, temos certeza de satisfazer seus desejos de grandeza!\"",
  ui_story_30960601_8_dialog_content = "\"As aulas começam apenas em 1998, e os instrutores virão à sua porta para as aulas!\"",
  ui_story_30960601_9_dialog_content = "\"A partir de agora, você também pode mudar toda a sua vida para melhor!\"",
  ui_story_30960601_10_dialog_content = "Huh. Parece meio interessante.",
  ui_story_30960601_11_dialog_content = "Com licença posso entrar?",
  ui_story_30960601_12_dialog_content = "Claro.",
  ui_story_30960601_13_dialog_content = "Olá, eu sou o <color=#FFB400>instrutor</color> despachado pela Rising Star Agency. Como vai?",
  ui_story_30960601_17_dialog_content = "S-Sariel?! Por que você é...?",
  ui_story_30960601_18_dialog_content = "*Tosse* Estou, uh... Trabalhando para a Rising Star Agency no momento.",
  ui_story_30960601_19_dialog_content = "Isso está debaixo da mesa - os benefícios para o trabalho são de outro mundo!",
  ui_story_30960601_20_dialog_content = "Eles até me dão roupas!",
  ui_story_30960601_21_dialog_content = "Isso é ótimo, mas... Por que você está me contando tudo isso?",
  ui_story_30960601_22_dialog_content = "Bem, não temos permissão para compartilhar nenhuma dessas informações com outras pessoas... Mas por sermos tão próximos, pensei em lhe contar sobre isso.",
  ui_story_30960601_23_dialog_content = "Esta também é a primeira vez que ensino uma aula, então, por favor, me perdoe se eu cometer alguns erros aqui e ali.",
  ui_story_30960601_23X_dialog_content = "Tá. Entendi.",
  ui_story_30960601_24_dialog_content = "Ahem... Então sem mais delongas, vamos começar.",
  ui_story_30960601_25_dialog_content = "As classes que você selecionou são: \"Como Evitar Conflitos com os Outros\", \"Técnicas Secretas: Comandar\" e \"O Caminho para a Riqueza\".",
  ui_story_30960601_26_dialog_content = "Começaremos com nossa primeira lição: Como evitar conflitos com os outros.",
  ui_story_30960601_27_dialog_content = "Antes de começarmos, gostaria de fazer algumas perguntas...",
  ui_story_30960601_28_dialog_content = "Se alguém lhe pedisse para se juntar à equipe dela, mas você realmente não quisesse se juntar, como você responderia?",
  ui_story_30960601_29_dialog_content = "O que isso tem a ver com conflito?",
  ui_story_30960601_30_dialog_content = "Uh, estou simplesmente tentando entender melhor sua personalidade, para que possamos estabelecer um método positivo de comunicação...",
  ui_story_30960601_31_dialog_content = "Em todo caso, qual é a sua resposta?",
  ui_story_30960601_32_dialog_content = "R: Agradeça a ela por seu amável convite e recuse respeitosamente.",
  ui_story_30960601_33_dialog_content = "B: Rejeite-a rudemente.",
  ui_story_30960601_34_dialog_content = "Recusar respeitosamente",
  ui_story_30960601_35_dialog_content = "Ah, entendi... Essa pergunta é pra ver se eu posso tomar a iniciativa para evitar possíveis conflitos, né?",
  ui_story_30960601_36_dialog_content = "Claro que eu escolheria recusar educadamente depois de agradecer a ela!",
  ui_story_30960601_37_dialog_content = "Correto. Você é bastante perceptivo, não é?",
  ui_story_30960601_38_dialog_content = "Recusá-la rudemente",
  ui_story_30960601_39_dialog_content = "Bem, teve uma pessoa que me convidou para me tornar um Eclipsite... Era como me convidar para fazer parte do time dela, de certa forma.",
  ui_story_30960601_40_dialog_content = "Depois disso, eu a recusei de forma bem grosseira... E então eu a derrotei na batalha.",
  ui_story_30960601_41_dialog_content = "Bem, dada a situação... suponho que haja alguma razão por trás dessa escolha de ação, certo?",
  ui_story_30960601_42_dialog_content = "Agora então, próxima pergunta...",
  ui_story_30960601_43_dialog_content = "Se alguém pegasse algo que pertencesse a você e se recusasse a devolvê-lo, o que você faria?",
  ui_story_30960601_44_dialog_content = "R: Pedir educadamente que se expliquem...",
  ui_story_30960601_45_dialog_content = "Oh! Houve alguém que roubou um componente que pertencia aos celestitas...",
  ui_story_30960601_46_dialog_content = "Mesmo que não pertencesse exclusivamente a mim, eu não podia simplesmente deixá-lo cair nas mãos daquela pessoa.",
  ui_story_30960601_47_dialog_content = "Então eu escolho B! Derrote-a e pegue de volta o componente!",
  ui_story_30960601_48_dialog_content = "Uh... Sua resposta está um pouco fora da caixa, então deixe-me apenas verificar meu panfleto bem rápido...",
  ui_story_30960601_49_dialog_content = "Aham, muito bem. E você acha que sua escolha foi a certa?",
  ui_story_30960601_50_dialog_content = "Não... As coisas nunca são tão simples quanto vocês pensam.",
  ui_story_30960601_51_dialog_content = "<size=45>Eles nunca são tão simples!</size>",
  ui_story_30960601_52_dialog_content = "P-Por que você teve que levantar a voz e dizer isso uma segunda vez?",
  ui_story_30960601_53_dialog_content = "Porque é isso que o panfleto nos diz para fazer.",
  ui_story_30960601_54_dialog_content = "Oh, espere... Nossos panfletos nos dizem para colocar anúncios ocasionalmente durante as aulas. Eu quase esqueci!",
  ui_story_30960601_55_dialog_content = "Huh? Jogar o que, agora...?",
  ui_story_30960601_56_dialog_content = "\"Ainda preso levando uma vida mal sucedida?\"",
  ui_story_30960601_57_dialog_content = "\"Ainda quebrando a cabeça sobre como melhorar a si mesmo?\"",
  ui_story_30960601_58_dialog_content = "\"O sucesso não é um método ou uma condição, mas um estado de espírito!\"",
  ui_story_30960601_59_dialog_content = "\"Deixe nossos cursos especiais guiá-lo para uma vida melhor!\"",
  ui_story_30960601_60_dialog_content = "\"Aja agora, e você pode receber um desconto de 20% em todas as aulas fazendo com que seus amigos se inscrevam também!\"",
  ui_story_30960601_61_dialog_content = "...",
  ui_story_30960601_62_dialog_content = "Gostaria de se inscrever?",
  ui_story_30960601_63_dialog_content = "Inscreva-me para mais cinco aulas!",
  ui_story_30960601_64_dialog_content = "Se for por conhecimento, não me importo de gastar um dinheirinho extra.",
  ui_story_30960601_65_dialog_content = "Tenho certeza que Vice também vai entender!",
  ui_story_30960601_66_dialog_content = "Obrigado por seu patrocínio! Você não tem ideia do quanto isso me ajuda!",
  ui_story_30960601_67_dialog_content = "Como assim?",
  ui_story_30960601_68_dialog_content = "Er, n-nada! Enfim, devemos continuar com a lição...",
  ui_story_30960601_69_dialog_content = "Não precisa",
  ui_story_30960601_70_dialog_content = "Eu não tenho muito dinheiro ultimamente...",
  ui_story_30960601_71_dialog_content = "Mas você não é o famoso Navigator?",
  ui_story_30960601_72_dialog_content = "Você tem conexões e um Colossus para arrancar! Tenho certeza que um pouco de dinheiro não é um problema...",
  ui_story_30960601_73_dialog_content = "Bem, manter o Colosso no ar e garantir que todos estejam confortáveis e felizes também custa dinheiro...",
  ui_story_30960601_74_dialog_content = "Eu não deveria gastar mais, então vamos continuar com a aula.",
  ui_story_30960601_75_dialog_content = "Está bem então. Não posso obrigá-lo se você não estiver disposto a fazê-lo... Vamos continuar, então...",
  ui_story_30960601_76_dialog_content = "O conflito pode ser dividido em vários tipos. Permita-me ilustrar isso com um desenho.",
  ui_story_30960601_77_dialog_content = "E... Mais um desenho...",
  ui_story_30960601_78_dialog_content = "E outra... E outra...",
  ui_story_30960601_79_dialog_content = "Uh... Sariel? Quantos desenhos mais você vai fazer?",
  ui_story_30960601_80_dialog_content = "Espere! Eu preciso desenhar mais um para torná-lo simétrico!",
  ui_story_30960601_81_dialog_content = "Oh, eu esqueci completamente que você é tudo sobre simetria...",
  ui_story_30960601_82_dialog_content = "Agora que estamos falando sobre isso, suas meias... Só a da direita tem um buraco.",
  ui_story_30960601_83_dialog_content = "O quê?!",
  ui_story_30960601_84_dialog_content = "Um segundo, deixe-me fazer um buraco no esquerdo...",
  ui_story_30960601_85_dialog_content = "Além disso, eles são chamados de meias, não meias.",
  ui_story_30960601_86_dialog_content = "Esqueça como eles são chamados, o ponto é...",
  ui_story_30960601_87_dialog_content = "Eu nunca pensei que você estragaria suas roupas assim só para torná-las simétricas.",
  ui_story_30960601_88_dialog_content = "Mas você já sabe que coisas assimétricas me deixam muito desconfortável!",
  ui_story_30960601_89_dialog_content = "Por que você se importa tanto com simetria, afinal? Ir tão longe é um pouco demais, sabe...",
  ui_story_30960601_90_dialog_content = "Porque simetria implica equilíbrio e estabilidade! Além disso, solenidade e beleza!",
  ui_story_30960601_91_dialog_content = "Eu chamo isso de senso de estética de simetria.",
  ui_story_30960601_92_dialog_content = "Vocês sabiam que...",
  ui_story_30960601_93_dialog_content = "Os lados esquerdos de nossos rostos não são cem por cento simétricos com os lados direitos.",
  ui_story_30960601_94_dialog_content = "Mas quando olhamos no espelho, tendemos a ignorá-lo.",
  ui_story_30960601_95_dialog_content = "Isso ocorre porque nascemos com um desejo inato de simetria...",
  ui_story_30960601_96_dialog_content = "Não é só porque a diferença é muito pequena para notar?",
  ui_story_30960601_97_dialog_content = "Huh? Você está questionando seriamente todas as pesquisas que fiz sobre estética de simetria?",
  ui_story_30960601_98_dialog_content = "Uh... Esqueça que eu disse qualquer coisa. Mas os chifres na sua cabeça também não são simétricos?",
  ui_story_30960601_99_dialog_content = "Ah! D-Não traga isso à tona! É difícil o suficiente apenas tentar esquecê-lo!",
  ui_story_30960601_100_dialog_content = "Vamos apenas voltar para a lição em mãos!",
  ui_story_30960601_101_dialog_content = "Tudo bem, então... Você poderia explicar mais sobre os desenhos que você fez agora?",
  ui_story_30960601_102_dialog_content = "Deixe-me ver o que diz o panfleto...",
  ui_story_30960601_103_dialog_content = "Você não parece muito familiarizado com os materiais do seu curso... Você pode realmente dar aulas assim?",
  ui_story_30960601_104_dialog_content = "Desculpe, o chefe da Rising Star Agency organizou isso para mim no último minuto, então estou tendo dificuldade em entender também.",
  ui_story_30960601_105_dialog_content = "Parece-me pouco confiável...",
  ui_story_30960601_107_dialog_content = "Grrr... Por que nenhuma dessas letras está alinhada uma com a outra?",
  ui_story_30960601_108_dialog_content = "Hã?",
  ui_story_30960601_109_dialog_content = "No panfleto, viu? As últimas linhas estão completamente desalinhadas!",
  ui_story_30960601_110_dialog_content = "\"'Como Evitar Conflitos com Outros', Subseção 2:\"",
  ui_story_30960601_111_dialog_content = "\"Após a primeira rodada de perguntas, deveríamos ter estabelecido uma forma positiva de comunicação com o cliente.\"",
  ui_story_30960601_112_dialog_content = "\"Neste momento, esta é a nossa melhor oportunidade para explicar nossa filosofia de marketing!\"",
  ui_story_30960601_113_dialog_content = "As letras não estão perfeitamente alinhadas, e isso está me deixando louco!",
  ui_story_30960601_114_dialog_content = "Acho que o conteúdo do panfleto é muito mais preocupante do que as próprias cartas, Sariel!",
  ui_story_30960601_115_dialog_content = "Soroz me ensinou por dezessete anos... E posso te dizer, não é assim que uma aula deve ser ministrada.",
  ui_story_30960601_116_dialog_content = "As aulas devem ser espaços para compartilhar e receber conhecimento.",
  ui_story_30960601_117_dialog_content = "É verdade, também não são nada como as lições que tive no passado... Mas talvez este seja apenas o mais novo método de ensino?",
  ui_story_30960601_118_dialog_content = "Eles até nos deram treinamento também...",
  ui_story_30960601_119_dialog_content = "Em que eles te treinaram?",
  ui_story_30960601_120_dialog_content = "Bem, eles nos mostraram como nos apresentar e nossos currículos...",
  ui_story_30960601_121_dialog_content = "E como incentivar nossos clientes a se manterem matriculados nas aulas... E como <color=#FFB400>promova ainda mais aulas para eles</color>...",
  ui_story_30960601_122_dialog_content = "Isso soa muito suspeito!",
  ui_story_30960601_123_dialog_content = "Se você tiver dúvidas, comentários ou preocupações, sinta-se à vontade para preencher este formulário.",
  ui_story_30960601_124_dialog_content = "Além disso, lembre-se de classificar sua experiência de aula comigo hoje como altamente satisfatória!",
  ui_story_30960601_125_dialog_content = "Mas por que? não estou nada satisfeito...",
  ui_story_30960601_126_dialog_content = "Porque enquanto você fizer isso, poderei colher todos os benefícios do meu trabalho.",
  ui_story_30960601_127_dialog_content = "Se você não fizer isso, eles vão descontar meu pagamento em vez disso.",
  ui_story_30960601_128_dialog_content = "Estou praticamente falido e preciso desses benefícios para continuar ganhando a vida.",
  ui_story_30960601_129_dialog_content = "Se eles descontarem meu pagamento...",
  ui_story_30960601_130_dialog_content = "Como vou me alimentar ou alimentar meu gato...?",
  ui_story_30960601_131_dialog_content = "D-Não se preocupe. Com certeza classificarei a lição como altamente satisfatória!",
  ui_story_30960601_132_dialog_content = "Mas você não acha que é um pouco duro da parte deles deduzir seu pagamento se você não obtiver a melhor classificação possível?",
  ui_story_30960601_133_dialog_content = "Sem mencionar todos aqueles outros... pontos questionáveis.",
  ui_story_30960601_134_dialog_content = "Definitivamente, há algo errado com este lugar da Rising Star Agency!",
  ui_story_30960601_135_dialog_content = "Como qual?",
  ui_story_30960601_136_dialog_content = "Espere, deixe-me perguntar a algumas pessoas experientes no mercado sobre isso...",
  ui_story_30960601_137_dialog_content = "É uma farsa, não é?",
  ui_story_30960601_138_dialog_content = "Definitivamente uma farsa.",
  ui_story_30960601_139_dialog_content = "Você foi enganado para trabalhar para uma organização obscura.",
  ui_story_30960601_140_dialog_content = "Eu posso dizer que isso é um <color=#FFB400>esquema de marketing multinível</color> só de olhar. Isso não é algo que um negócio honesto faria.",
  ui_story_30960601_143_dialog_content = "M-Mas eu já assinei um contrato com a Rising Star Agency, e paguei um depósito...",
  ui_story_30960601_144_dialog_content = "*Suspiro* Não vá procurar trabalho em lugares suspeitos como este!",
  ui_story_30960601_145_dialog_content = "Há todos os tipos de negócios em Umbraton. Alguns são legítimos, e alguns são tudo menos isso.",
  ui_story_30960601_146_dialog_content = "Você precisa manter os olhos abertos para locais de trabalho credíveis com formação e história sólidas!",
  ui_story_30960601_147_dialog_content = "Vou voltar e pedir ao Clã para investigar essa Agência Rising Star.",
  ui_story_30960601_148_dialog_content = "Se você tiver algum documento assinado, sugiro que me deixe vê-lo agora.",
  ui_story_30960601_149_dialog_content = "Tenho certeza de que a papelada inclui termos e condições destinados a atacar os desavisados.",
  ui_story_30960601_150_dialog_content = "Obrigado, muito obrigado.",
  ui_story_30960601_151_dialog_content = "Se eles realmente são uma agência fraudulenta, então o dinheiro que paguei...",
  ui_story_30960601_152_dialog_content = "Foi tudo um desperdício, não foi?!",
  ui_story_30960601_153_dialog_content = "1998 Nightium... Todo o meu dinheiro de bolso suado...",
  ui_story_30960601_154_dialog_content = "Tudo o que eu queria era aprender algum conhecimento novo e valioso. Eu nunca pensei...",
  ui_story_30960601_155_dialog_content = "Não se preocupe, PlayerName. Ainda pretendo terminar de dar suas aulas.",
  ui_story_30960601_156_dialog_content = "Eles nos deram esses panfletos, mas também tenho meus próprios materiais de curso para usar.",
  ui_story_30960601_157_dialog_content = "Eu li muitos livros, só para estar mais preparado para isso. Veja, eu também tenho minhas próprias anotações!",
  ui_story_30960601_158_dialog_content = "Sariel, você...",
  ui_story_30960601_159_dialog_content = "E olhe! Cada linha está perfeitamente alinhada!",
  ui_story_30960601_160_dialog_content = "Esse é realmente o ponto...?",
  ui_story_30960601_161_dialog_content = "De qualquer forma, cansei de seguir o panfleto deles... Então, você ainda está disposto a fazer minha aula?",
  ui_story_30960601_162_dialog_content = "Claro que não!",
  ui_story_30960601_163_dialog_content = "Ótimo, então vamos levá-lo desde o início.",
  ui_story_30960601_164_dialog_content = "Agora, para entender o conflito, devemos primeiro entender sua definição.",
  ui_story_30960601_165_dialog_content = "\"A definição de conflito enfatiza principalmente a existência e a consciência das diferenças de interesses...\"",
  ui_story_30960601_167_dialog_content = "Ainda temos muito tempo nesta aula, então vou me certificar de elaborar todos esses pontos com cuidado.",
  ui_story_30960601_168_dialog_content = "Excelente! Exatamente como uma aula real deve ser!",
  ui_story_30960601_169_dialog_content = "Heh, que estudante obediente você é, PlayerName...",
  ui_story_30960602_1_dialog_content = "Tenho ótimas notícias, PlayerName!",
  ui_story_30960602_2_dialog_content = "Eu deveria poder te pagar de volta por ter comprado meu almoço outro dia!",
  ui_story_30960602_3_option_content = "Não se preocupe, foi por minha conta...",
  ui_story_30960602_4_dialog_content = "Isso não vai funcionar. O vovô costumava dizer que até irmãs devem se pagar após emprestar dinheiro uma à outra.",
  ui_story_30960602_5_dialog_content = "Além disso, alguém me ofereceu um trabalho super lucrativo!",
  ui_story_30960602_6_option_content = "A Senhora Sheol ofereceu um novo emprego para você?",
  ui_story_30960602_7_dialog_content = "É um emprego novo, mas não é dela.",
  ui_story_30960602_8_dialog_content = "A localização também parece ser realmente de alto nível.",
  ui_story_30960602_9_dialog_content = "Então, o que exatamente o trabalho envolve?",
  ui_story_30960602_10_dialog_content = "Me disseram que até um desajeitado como eu deveria ser capaz de lidar com isso.",
  ui_story_30960602_11_dialog_content = "Tudo o que tenho que fazer é sentar à mesa e jogar o dia todo.",
  ui_story_30960602_12_dialog_content = "Jogar?",
  ui_story_30960602_13_dialog_content = "Sim! É um daqueles jogos em que jogam uma bolinha em uma roda giratória com muitos números nela.",
  ui_story_30960602_14_dialog_content = "... Quer dizer, tipo uma roleta?",
  ui_story_30960602_15_dialog_content = "Não tenho certeza, mas mesmo que eu costume estragar as coisas, jogar é algo que sempre fui bom!",
  ui_story_30960602_16_dialog_content = "Espere, então você concordou em fazer isso sem nem mesmo conhecer o jogo?",
  ui_story_30960602_17_dialog_content = "Tem certeza de que não está sendo enganado ou algo assim? Muitos golpistas costumam aparecer conforme o ano novo se aproxima...",
  ui_story_30960602_18_dialog_content = "De jeito nenhum! Além disso, já fui enganado no mês passado; quais são as chances de isso acontecer duas vezes em dois meses?",
  ui_story_30960602_19_dialog_content = "Acho que eu deveria ir com você, só para garantir a segurança...",
  ui_story_30960602_20_dialog_content = "Estou preocupado que você possa se meter em sérios problemas desta vez.",
  ui_story_30960602_21_dialog_content = "Você não acha que está me subestimando?",
  ui_story_30960602_22_dialog_content = "Ainda assim, eu não me importo se você vier junto. Afinal, o chefe diz que eu sou pago por dia.",
  ui_story_30960602_23_dialog_content = "Assim que eu sacar meu salário, poderei te pagar de volta e te levar para uma boa refeição. Até terá frango!",
  ui_story_30960602_24_dialog_content = "<color=#e8d9bb>No dia seguinte, após chegar ao local designado de Sariel.</color>",
  ui_story_30960602_25_dialog_content = "...",
  ui_story_30960602_26_dialog_content = "Ei, PlayerName!",
  ui_story_30960602_27_dialog_content = "O que há com essas roupas...?",
  ui_story_30960602_28_dialog_content = "O chefe me deu e disse que isso me impediria de chamar muita atenção.",
  ui_story_30960602_29_dialog_content = "E-Eu entendo... Eles realmente têm uma certa atmosfera subterrânea.",
  ui_story_30960602_30_dialog_content = "(Que roupa inacreditável...)",
  ui_story_30960602_31_dialog_content = "Mas... eu realmente... não suporto eles...",
  ui_story_30960602_32_dialog_content = "<color=#e8d9bb>Sariel sofre de transtorno obsessivo-compulsivo, especialmente quando se trata de objetos assimétricos.</color>",
  ui_story_30960602_33_dialog_content = "<color=#e8d9bb>A condição dela é tão séria que, se ela tiver um rasgo em uma meia, ela rasgará um buraco na outra só para combinar.</color>",
  ui_story_30960602_34_dialog_content = "<color=#e8d9bb>Eu tenho que dizer, essa roupa que ela está usando agora está tocando em todos os seus pontos fracos—</color>",
  ui_story_30960602_35_dialog_content = "<color=#e8d9bb>Um acessório de cabelo assimétrico.</color>",
  ui_story_30960602_36_dialog_content = "<color=#e8d9bb>Um vestido assimétrico.</color>",
  ui_story_30960602_37_dialog_content = "<color=#e8d9bb>E meias assimétricas.</color>",
  ui_story_30960602_38_dialog_content = "Tadinha...",
  ui_story_30960602_39_dialog_content = "(Ela não vai realmente chorar, vai...?)",
  ui_story_30960602_40_dialog_content = "Uh, Sariel? Você já falou sobre isso com aquele trapaceiro... quer dizer, seu chefe?",
  ui_story_30960602_41_dialog_content = "Eu fiz... mas o chefe disse...",
  ui_story_30960602_42_dialog_content = "Você está mesmo reclamando das roupas grátis que te dei? Que pretensioso.",
  ui_story_30960602_43_dialog_content = "Morar em Umbraton todos esses anos tirou seu bom senso?",
  ui_story_30960602_44_dialog_content = "Muitas pessoas estão implorando por um trabalho bacana como este. Se você não quiser, tenho certeza de que outra pessoa vai aceitar!",
  ui_story_30960602_45_dialog_content = "Sério, olhe só para você! Depois de todos esses anos, você realmente aumentou seu patrimônio líquido? Você pode realmente dizer que tem se esforçado ao máximo?",
  ui_story_30960602_46_dialog_content = "Como espera ganhar dinheiro quando está disposto a desistir por algo tão insignificante?",
  ui_story_30960602_47_dialog_content = "... É isso.",
  ui_story_30960602_48_dialog_content = "Isso está muito fora dos limites!",
  ui_story_30960602_49_dialog_content = "Ele também disse que não vou receber pagamento se eu não usar essas roupas e terei que pagar de volta se elas rasgarem.",
  ui_story_30960602_50_dialog_content = "Então, apesar de tudo, você ainda quer fazer esse trabalho?",
  ui_story_30960602_51_dialog_content = "... EU...",
  ui_story_30960602_52_dialog_content = "... Eu tenho minhas razões para ganhar dinheiro, então quero tentar.",
  ui_story_30960602_53_dialog_content = "Obrigado por vir comigo, aliás. Com você por perto... Acho que consigo lidar um pouco melhor...",
  ui_story_30960602_54_dialog_content = "Sariel...",
  ui_story_30960602_55_dialog_content = "(No começo, eu só queria ter certeza de que ela não estava sendo enganada, mas agora me sinto obrigado a ajudá-la a terminar o trabalho.)",
  ui_story_30960602_56_dialog_content = "Não se preocupe, vou ajudá-lo no que puder.",
  ui_story_30960602_57_dialog_content = "Buáá... Estou tão grato! Não consigo imaginar o que aconteceria comigo sem você aqui!",
  ui_story_30960602_58_dialog_content = "Haha, não mencione isso. Já está quase na hora de bater o ponto, certo? Vamos lá.",
  ui_story_30960602_59_dialog_content = "<color=#e8d9bb>Na casa de jogos subterrânea.</color>",
  ui_story_30960602_60_dialog_content = "<color=#e8d9bb>O som de rodas girando e dados rolando pode ser ouvido por todo o lugar, enquanto as pessoas olham atentamente para as cartas sendo viradas em suas mesas.</color>",
  ui_story_30960602_61_dialog_content = "<color=#e8d9bb>A multidão ao redor das mesas vibra e lamenta conforme os jogos continuam.</color>",
  ui_story_30960602_62_dialog_content = "(Eu acho que não sou feito para um lugar assim...)",
  ui_story_30960602_63_dialog_content = "(Mas é pelo Sariel, então tenho que cerrar os dentes e aguentar!)",
  ui_story_30960602_64_dialog_content = "Então, seu chefe também está aqui, Sariel?",
  ui_story_30960602_65_dialog_content = "Sim, eu o vi há um segundo atrás. Ele está bem ali... Hã? Onde ele foi?",
  ui_story_30960602_66_dialog_content = "Acho que não importa. Ele me deu esse pequeno receptor para colocar no meu ouvido, que posso usar para alcançá-lo sempre que precisar. Ah, ele está me chamando agora!",
  ui_story_30960602_67_dialog_content = "A pessoa ao meu lado? Você quer dizer PlayerName? Ele está aqui para me ajudar... Quer dizer, ele é apenas um amigo.",
  ui_story_30960602_68_dialog_content = "Ok, então primeiro eu preciso trocar o dinheiro que você me deu por fichas e depois sentar em uma daquelas mesas...",
  ui_story_30960602_69_dialog_content = "Depois disso, eu só escolho um número... e entrego as minhas fichas...",
  ui_story_30960602_70_dialog_content = "E-Espere, você está oferecendo todas as suas fichas?!",
  ui_story_30960602_71_dialog_content = "Ah, isso é uma coisa ruim?",
  ui_story_30960602_72_dialog_content = "Você não deveria ir com tudo no seu primeiro jogo!",
  ui_story_30960602_73_dialog_content = "Trinta e sete, preto. Parabéns, senhorita, você ganhou.",
  ui_story_30960602_74_dialog_content = "Mas ele disse que eu ganhei! E olha, ele me deu um monte de fichas!",
  ui_story_30960602_75_dialog_content = "Como exatamente eu ganhei? Foi porque eu ofereci mais fichas?",
  ui_story_30960602_76_dialog_content = "Sorte de iniciante, eu suponho... De qualquer forma, não vá all-in assim novamente. Comece com um ou dois tokens e vá progredindo.",
  ui_story_30960602_77_dialog_content = "Ok, você é o chefe. Afinal, você parece saber mais sobre isso do que eu.",
  ui_story_30960602_78_dialog_content = "Eu também não entendo muito bem, mas um dos meus amigos me ensinou alguns truques antes.",
  ui_story_30960602_79_dialog_content = "(Mesmo que eu tenha aprendido isso apenas para evitar ser enganado, parece que finalmente posso colocá-lo em bom uso...)",
  ui_story_30960602_80_dialog_content = "Então, o que exatamente significa \"all-in\"?",
  ui_story_30960602_81_dialog_content = "...",
  ui_story_30960602_82_dialog_content = "Dois, vermelho. Parabéns, Senhorita, você ganhou.",
  ui_story_30960602_83_dialog_content = "Inacreditável...",
  ui_story_30960602_84_dialog_content = "Vinte e cinco vitórias seguidas! Essa garota deve ser a própria Dona Sorte!",
  ui_story_30960602_85_dialog_content = "Temos que chegar ao nível dela também!",
  ui_story_30960602_86_dialog_content = "Uh, PlayerName? Por que todo mundo está olhando para mim?",
  ui_story_30960602_87_dialog_content = "Esse jogo não é tão difícil. Contanto que você ofereça um número par de fichas, você sempre ganha.",
  ui_story_30960602_88_dialog_content = "Se eu fosse você, falaria baixo. Teríamos problemas se aquelas pessoas te ouvissem depois de perder tantas vezes.",
  ui_story_30960602_89_dialog_content = "Realmente parece bem estranho. Você já ganhou vinte e cinco vezes... E apenas apostando em números únicos, ainda por cima.",
  ui_story_30960602_90_dialog_content = "Mesmo com uma sorte incrível, isso parece muito improvável. Talvez a casa de jogos esteja usando você como isca?",
  ui_story_30960602_91_dialog_content = "O que você quer dizer com \"cúmplice\"?",
  ui_story_30960602_92_dialog_content = "... Deixa pra lá. Levaria muito tempo para explicar.",
  ui_story_30960602_93_dialog_content = "De qualquer forma, mal consigo segurar todas essas fichas... Acho que isso deve ser suficiente por enquanto.",
  ui_story_30960602_94_dialog_content = "Hã? É o chefe de novo...",
  ui_story_30960602_95_dialog_content = "O que é isso? Você quer que eu continue jogando ou então não vou receber? Mas por quê...?",
  ui_story_30960602_96_dialog_content = "Seu chefe quer que você continue?",
  ui_story_30960602_97_dialog_content = "Bem, não é a coisa mais honesta a se fazer, mas se é isso que ele quer de você... Acho que tudo bem.",
  ui_story_30960602_98_dialog_content = "Então qual é o sentido de tudo isso? Estou começando a ficar entediado... E essas roupas estão me deixando louco...",
  ui_story_30960602_99_dialog_content = "Bocejo—<size=45>Uau!</size>",
  ui_story_30960602_100_dialog_content = "Sariel esbarra em sua montanha de fichas ao esticar as costas, mas consegue evitar derrubá-la, desviando-se a tempo.",
  ui_story_30960602_101_dialog_content = "Infelizmente, o movimento desajeitado faz com que ela chute a cadeira para longe e esbarre na mesa.",
  ui_story_30960602_102_dialog_content = "É preciso uma certa habilidade para cair de forma tão espetacular.",
  ui_story_30960602_103_dialog_content = "Ai...",
  ui_story_30960602_104_dialog_content = "... Você está bem? Se machucou agora há pouco?",
