  ui_story_30960602_126_dialog_content = "<color=#e8d9bb>Graças à resposta extremamente rápida deles, os funcionários rapidamente prendem o velhote trapaceiro.</color>",
  ui_story_30960602_127_dialog_content = "<color=#e8d9bb>Logo depois, todas as vitórias e derrotas naquela mesa foram consideradas inválidas.</color>",
  ui_story_30960602_128_dialog_content = "<color=#e8d9bb>Em outras palavras, o tempo e esforço que Sariel e eu gastamos aqui foi tudo em vão.</color>",
  ui_story_30960602_129_dialog_content = "Devo dizer, isso não é como eu esperava que as coisas terminassem de jeito nenhum.",
