  ui_story_30960602_134_dialog_content = "De novo, você provavelmente não entendeu nada do que eu acabei de dizer...",
  ui_story_30960602_135_dialog_content = "Por que ele me usaria para trapacear em vez de fazer isso ele mesmo?",
  ui_story_30960602_136_dialog_content = "Acho que ele estava usando você para desviar a atenção dele mesmo. Ao fazer você parecer a Senhora da Sorte, ele continuaria jogando sem despertar muita suspeita.",
  ui_story_30960602_137_dialog_content = "Aposto que as roupas que ele te deu também serviam para desviar os olhares das pessoas dele.",
  ui_story_30960602_138_dialog_content = "Entendi... Mas ainda não compreendo.",
  ui_story_30960602_139_dialog_content = "Então, o que devo fazer sobre essa roupa?",
