  ui_story_30960602_142_dialog_content = "Além disso... Está na hora de eu treinar para lidar com situações difíceis...",
  ui_story_30960602_143_dialog_content = "Como assim?",
  ui_story_30960602_144_dialog_content = "Passei um dia inteiro usando essas roupas horríveis, mas sempre que começava a me sentir desconfortável... eu pensava em você.",
